const input = $input.first().json;
const headers = input.headers || {};
const secret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
if (secret !== 'YOUR_WEBHOOK_SECRET') {
  throw new Error('Unauthorized: invalid or missing X-Webhook-Secret header');
}
const body = input.body || input;
const question = String(body.question || '').trim().slice(0, 1200);
if (!question) throw new Error('Missing assistant question');
const allowedActions = Array.isArray(body.allowedActions) ? body.allowedActions : [];
const safe = {
  question,
  currentPage: body.currentPage || 'overview',
  clinicName: body.clinicName || 'Clinic',
  activeClients: Number(body.activeClients || 0),
  newInquiries: Number(body.newInquiries || 0),
  staleInquiries: Number(body.staleInquiries || 0),
  awaitingReply: Number(body.awaitingReply || 0),
  atRiskClients: Number(body.atRiskClients || 0),
  lapsedClients: Number(body.lapsedClients || 0),
  vipClients: Number(body.vipClients || 0),
  noShowRate30d: Number(body.noShowRate30d || 0),
  appointmentsNext48h: Number(body.appointmentsNext48h || 0),
  recoveryPulse7d: body.recoveryPulse7d || {},
  openAssistantTasks: Array.isArray(body.openAssistantTasks) ? body.openAssistantTasks.slice(0, 10) : [],
  launchGaps: Array.isArray(body.launchGaps) ? body.launchGaps.slice(0, 12) : [],
  allowedActions
};
return [{ json: safe }];

const raw = $input.first().json || {};
let text = raw.output_text || raw.output?.[0]?.content?.[0]?.text || raw.content?.[0]?.text || '';
let parsed = null;
try { parsed = JSON.parse(text); } catch (e) { parsed = null; }
const fallback = {
  answer: 'I could not get a clean GPT response, but the dashboard assistant can still help with built-in actions like launch readiness, recovery pulse, tasks, client lookup, and navigation.',
  reasoning_summary: 'The AI response was unavailable or invalid.',
  priority: 'medium',
  actions: [],
  follow_up_question: 'Do you want me to check launch readiness or recovery pulse instead?'
};
const allowedTypes = new Set(['navigate','open_client','mark_vip_after_confirmation','send_booking_confirmation_after_confirmation','draft_message','check_launch_readiness','create_task']);
const out = parsed && typeof parsed.answer === 'string' ? parsed : fallback;
out.answer = String(out.answer || fallback.answer).slice(0, 1800);
out.reasoning_summary = String(out.reasoning_summary || '').slice(0, 300);
out.priority = ['low','medium','high'].includes(out.priority) ? out.priority : 'medium';
out.follow_up_question = String(out.follow_up_question || '').slice(0, 300);
out.actions = Array.isArray(out.actions) ? out.actions.filter(a => a && allowedTypes.has(a.type)).slice(0, 3).map(a => ({
  label: String(a.label || a.type).slice(0, 60),
  type: a.type,
  args: a.args && typeof a.args === 'object' ? a.args : {},
  requiresConfirmation: !!a.requiresConfirmation
})) : [];
return [{ json: out }];
